<script lang="ts">
  let {entity, connections=[]}=$props();
  let depth=$state(2); let showLabels=$state(true); let selected=$state<any>(null); let scale=$state(1); let panX=$state(0); let panY=$state(0); let dragging=$state(false); let dragX=0,dragY=0,startPanX=0,startPanY=0;
  const W=1280,H=760,cx=640,cy=380;
  const direct=$derived(connections.slice(0,24));
  const second=$derived.by(()=>{const seen=new Set<number>();const out:any[]=[];for(const c of direct){for(const edge of (c.graph_second_hop??[])){const other=Number(edge.subject_id)===Number(c.connected_id)?{id:Number(edge.object_id),name:edge.object_name,type:edge.object_type,rfx:edge.object_gets_rfx_entity_id,supplier:edge.object_gets_supplier_entity_id}:{id:Number(edge.subject_id),name:edge.subject_name,type:edge.subject_type,rfx:edge.subject_gets_rfx_entity_id,supplier:edge.subject_gets_supplier_entity_id};if(other.id===Number(entity.id))continue;const key=Number(edge.id);if(seen.has(key))continue;seen.add(key);out.push({edge,parent:Number(c.connected_id),parentName:c.connected_name,...other});if(out.length>=60)return out;}}return out;});
  function parse(raw:any){try{return raw?JSON.parse(String(raw)):{};}catch{return {};}}
  function kindDirect(c:any){const m=parse(c.connected_metadata_json);if(c.connected_gets_rfx_entity_id)return 'tender';if(c.connected_gets_supplier_entity_id)return 'supplier';if(m?.gets?.kind==='agency'||c.connected_type==='public_agency')return 'agency';if(String(c.connected_slug??'').startsWith('charities-officer-')||c.connected_type==='person')return 'person';return String(c.connected_type||'other');}
  function kind2(n:any){if(n.rfx)return 'tender';if(n.supplier)return 'supplier';if(n.type==='public_agency')return 'agency';return String(n.type||'other');}
  function rootKind(){if(entity.entity_type==='public_agency')return 'agency';if(entity.entity_type==='person')return 'person';return String(entity.entity_type||'other');}
  function clean(name:any){return String(name||'Record').replace(/^Supplier record — /,'').replace(/ — RFx .*$/,'').replace(/^Procurement record RFx [^—]+ — /,'');}
  function fill(k:string){return k==='agency'?'#55c88a':k==='tender'?'#62a9e8':k==='supplier'?'#b984df':k==='charity'?'#e58a58':k==='person'?'#e6c65b':k==='company'?'#83b7ad':'#9aa7a2';}
  function labelKind(k:string){return k==='agency'?'Government agency':k==='tender'?'Government tender':k==='supplier'?'GETS supplier':k==='person'?'Officer / person':k==='charity'?'Charity':k==='company'?'Company':'Other entity';}
  function short(s:string,n=34){return s.length>n?s.slice(0,n-1)+'…':s;}
  function directPos(i:number,n:number){const a=(i/Math.max(n,1))*Math.PI*2-Math.PI/2;const rx=n<=8?300:330,ry=n<=8?235:260;return{x:cx+Math.cos(a)*rx,y:cy+Math.sin(a)*ry};}
  function secondPos(i:number,n:number){const a=(i/Math.max(n,1))*Math.PI*2-Math.PI/2+.045;return{x:cx+Math.cos(a)*535,y:cy+Math.sin(a)*325};}
  function dpos(id:number){const i=direct.findIndex((c:any)=>Number(c.connected_id)===id);return directPos(Math.max(i,0),direct.length);}
  function supplierCount(id:number){return second.filter((n:any)=>n.parent===Number(id)&&n.edge.predicate==='AWARDED_TO').length;}
  function selectSecond(n:any,k:string){selected={id:n.id,name:n.name,predicate:n.edge.predicate,kind:k,source:n.edge,parent:n.parent,parentName:n.parentName,level:2};}
  function selectDirect(c:any,k:string){selected={id:c.connected_id,name:c.connected_name,predicate:c.predicate,kind:k,source:c,level:1,suppliers:supplierCount(c.connected_id)};}
  function keySecond(e:KeyboardEvent,n:any,k:string){if(e.key==='Enter'||e.key===' '){e.preventDefault();selectSecond(n,k);}}
  function keyDirect(e:KeyboardEvent,c:any,k:string){if(e.key==='Enter'||e.key===' '){e.preventDefault();selectDirect(c,k);}}
  function fit(){scale=1;panX=0;panY=0;}
  function reset(){depth=2;showLabels=true;selected=null;fit();}
  function zoomBy(f:number){scale=Math.max(.5,scale*f);}
  function wheel(e:WheelEvent){e.preventDefault();zoomBy(e.deltaY<0?1.12:1/1.12);}
  function pointerDown(e:PointerEvent){if((e.target as Element)?.closest?.('.node'))return;dragging=true;dragX=e.clientX;dragY=e.clientY;startPanX=panX;startPanY=panY;(e.currentTarget as Element).setPointerCapture(e.pointerId);}
  function pointerMove(e:PointerEvent){if(!dragging)return;panX=startPanX+(e.clientX-dragX);panY=startPanY+(e.clientY-dragY);}
  function pointerUp(e:PointerEvent){dragging=false;try{(e.currentTarget as Element).releasePointerCapture(e.pointerId);}catch{}}
  function heading(s:any){if(s.kind==='supplier'&&s.predicate==='AWARDED_TO')return 'Awarded supplier';if(s.kind==='tender'&&s.predicate==='ISSUED')return 'Tender issued by '+clean(entity.canonical_name);if(s.predicate==='OFFICER_OF'||s.predicate==='officer_of')return 'Recorded officer relationship';return labelKind(s.kind)+' connection';}
  function summary(s:any){if(s.kind==='supplier'&&s.predicate==='AWARDED_TO'&&s.parentName)return `${clean(s.name)} is recorded as an awarded supplier for ${clean(s.parentName)}, a government tender issued by ${clean(entity.canonical_name)}.`;if(s.kind==='tender'&&s.predicate==='ISSUED')return `${clean(entity.canonical_name)} issued the government tender ${clean(s.name)}.${s.suppliers?` The graph currently shows ${s.suppliers} recorded awarded supplier${s.suppliers===1?'':'s'} connected to this tender.`:''}`;if(s.predicate==='OFFICER_OF'||s.predicate==='officer_of')return `${clean(s.name)} is linked by the source record through an officer relationship.`;return `${clean(s.name)} is connected to ${clean(entity.canonical_name)} by the recorded relationship “${String(s.predicate).replaceAll('_',' ').toLowerCase()}”.`;}
  function meaning(s:any){if(s.kind==='supplier'&&s.predicate==='AWARDED_TO')return 'GETS records link this supplier to the procurement as an awarded supplier. This establishes the recorded procurement relationship; it does not by itself establish the contract value, the amount of work actually performed, or any wrongdoing.';if(s.kind==='tender'&&s.predicate==='ISSUED')return 'This node represents a government procurement process published by the agency. Purple nodes connected through “Awarded to” are suppliers recorded in the source data for that procurement.';if(s.predicate==='OFFICER_OF'||s.predicate==='officer_of')return 'This means the public source records an officer relationship between these entities. It does not by itself imply ownership, control, influence, or wrongdoing.';return 'This connection reflects a relationship recorded in a public source. The connection alone does not imply wrongdoing, influence or endorsement.';}
</script>
<section class="graph-section">
  <div class="graph-head"><div><p class="eyebrow">Relationship explorer</p><h2>Graph view</h2></div><div class="head-actions"><span>{direct.length} direct · {second.length} second-hop</span><button onclick={fit}>Fit graph</button><button onclick={reset}>Reset</button></div></div>
  <div class="graph-shell">
    <aside class="legend panel"><strong>Legend</strong><span><i style={`background:${fill('agency')}`}></i>Government agency</span><span><i style={`background:${fill('tender')}`}></i>Government tender</span><span><i style={`background:${fill('supplier')}`}></i>GETS supplier</span><span><i style={`background:${fill('charity')}`}></i>Charity</span><span><i style={`background:${fill('person')}`}></i>Officer / person</span><span><i style={`background:${fill('company')}`}></i>Company</span><span><i style={`background:${fill('other')}`}></i>Other entity</span><div class="rel-legend"><strong>Relationships</strong><span><b class="line issued"></b>Issued</span><span><b class="line awarded"></b>Awarded to</span><span><b class="line officer"></b>Officer of</span><span><b class="line other"></b>Other</span></div></aside>
    <div class:dragging class="canvas" onwheel={wheel} onpointerdown={pointerDown} onpointermove={pointerMove} onpointerup={pointerUp} onpointercancel={pointerUp}>
      {#if connections.length===0}<div class="graph-empty">No connections are currently loaded for this record.</div>{:else}<svg viewBox={`0 0 ${W} ${H}`} role="img" aria-label={`Relationship graph for ${entity.canonical_name}`}><g transform={`translate(${panX} ${panY}) translate(${cx*(1-scale)} ${cy*(1-scale)}) scale(${scale})`}>
        {#if depth===2}{#each second as n,i}{@const a=dpos(n.parent)}{@const b=secondPos(i,second.length)}<line class:awarded={n.edge.predicate==='AWARDED_TO'} class:issued={n.edge.predicate==='ISSUED'} class="second-edge" x1={a.x} y1={a.y} x2={b.x} y2={b.y}/>{/each}{/if}
        {#each direct as c,i}{@const p=directPos(i,direct.length)}<line class:awarded={c.predicate==='AWARDED_TO'} class:issued={c.predicate==='ISSUED'} class:officer={c.predicate==='OFFICER_OF'||c.predicate==='officer_of'} class="direct-edge" x1={cx} y1={cy} x2={p.x} y2={p.y}/>{/each}
        {#if depth===2}{#each second as n,i}{@const p=secondPos(i,second.length)}{@const k=kind2(n)}<g class="node secondary" role="link" tabindex="0" onclick={()=>selectSecond(n,k)} onkeydown={(e)=>keySecond(e,n,k)}><circle class:selected={selected?.id===n.id} cx={p.x} cy={p.y} r="15" fill={fill(k)}/>{#if showLabels}<text class="node-label secondary-label" x={p.x} y={p.y+32} text-anchor="middle">{short(clean(n.name),28)}</text>{/if}</g>{/each}{/if}
        {#each direct as c,i}{@const p=directPos(i,direct.length)}{@const k=kindDirect(c)}<g class="node direct-node" role="link" tabindex="0" onclick={()=>selectDirect(c,k)} onkeydown={(e)=>keyDirect(e,c,k)}><circle class:selected={selected?.id===c.connected_id} cx={p.x} cy={p.y} r="22" fill={fill(k)}/>{#if showLabels}<text class="node-label direct-label" x={p.x} y={p.y+43} text-anchor="middle">{short(clean(c.connected_name),32)}</text>{/if}</g>{/each}
        <g class="center"><circle cx={cx} cy={cy} r="42" fill={fill(rootKind())}/><circle cx={cx} cy={cy} r="54" class="halo"/><text class="root-label" x={cx} y={cy+74} text-anchor="middle">{short(entity.canonical_name,42)}</text><text class="root-type" x={cx} y={cy+96} text-anchor="middle">{labelKind(rootKind())}</text></g>
      </g></svg>{/if}<div class="pan-hint">Drag to pan · Scroll to zoom</div><div class="zoom"><button aria-label="Zoom out" onclick={()=>zoomBy(1/1.2)}>−</button><span>{Math.round(scale*100)}%</span><button aria-label="Zoom in" onclick={()=>zoomBy(1.2)}>+</button></div>
    </div>
    <aside class="controls panel">
      {#if selected}<div class="inspector"><div class="inspector-top"><button class="back" onclick={()=>selected=null}>← Back</button><span class="type-dot" style={`background:${fill(selected.kind)}`}></span></div><small>{labelKind(selected.kind)}</small><h3>{clean(selected.name)}</h3><div class="relationship-pill">{String(selected.predicate).replaceAll('_',' ')}</div><h4>{heading(selected)}</h4><p>{summary(selected)}</p><div class="meaning"><strong>What this means</strong><p>{meaning(selected)}</p></div><div class="evidence"><strong>Evidence</strong>{#if selected.source?.publisher}<p>{selected.source.publisher}</p>{/if}{#if selected.source?.dataset}<p>{selected.source.dataset}</p>{/if}</div><div class="inspector-links"><a href={`/record/${selected.id}`}>Open {selected.kind==='tender'?'tender':'record'} →</a>{#if selected.parent}<a href={`/record/${selected.parent}`}>Open tender →</a>{/if}{#if selected.source?.source_url}<a href={selected.source.source_url} target="_blank" rel="noreferrer">View source evidence ↗</a>{/if}</div></div>
      {:else}<strong>Filters & display</strong><label><span>Depth</span><select bind:value={depth}><option value={1}>1 hop</option><option value={2}>2 hops</option></select></label><label class="check"><input type="checkbox" bind:checked={showLabels}/> Show labels</label><div class="control-rule"></div><strong>Graph</strong><p><b>{direct.length}</b> directly connected records</p><p><b>{depth===2?second.length:0}</b> second-hop connections</p><p class="help">Click a node to see a plain-English explanation of the recorded relationship and its evidence.</p><button class="reset" onclick={reset}>Reset to defaults</button>{/if}
    </aside>
  </div>
  <div class="graph-foot"><span>Every connection is based on evidence from a source.</span><span>Centre: <b>{entity.canonical_name}</b> (ID: {entity.id})</span></div>
  <p class="graph-disclaimer"><strong>What does a connection mean?</strong> Lines show relationships found in public records. A connection does not by itself imply wrongdoing, influence or endorsement. Check the record's source evidence for context.</p>
</section>
<style>
.graph-section{margin-top:38px}.graph-head{display:flex;justify-content:space-between;align-items:end;margin-bottom:12px}.graph-head h2{font-family:Georgia,'Times New Roman',serif;font-size:32px;margin:2px 0}.eyebrow{font-size:12px;text-transform:uppercase;letter-spacing:.08em;color:#176b5a;font-weight:700;margin:0}.head-actions{display:flex;align-items:center;gap:8px;color:#68726e;font-size:12px}.head-actions button,.reset{border:1px solid #40504c;background:#18211f;color:#e2ebe8;padding:8px 11px;cursor:pointer}.graph-shell{position:relative;display:grid;grid-template-columns:190px minmax(0,1fr) 260px;min-height:760px;background:#0e1514;border:1px solid #293532;overflow:hidden}.panel{z-index:2;color:#cbd8d3;padding:22px 18px;font-size:12px;background:#101715}.panel>strong,.rel-legend strong{display:block;color:#fff;text-transform:uppercase;letter-spacing:.09em;font-size:10px;margin-bottom:18px}.legend span{display:flex;align-items:center;gap:9px;margin:12px 0}.legend i{width:12px;height:12px;border-radius:50%;display:inline-block;box-shadow:0 0 0 2px #ffffff18}.rel-legend{border-top:1px solid #2b3734;margin-top:25px;padding-top:20px}.rel-legend .line{width:23px;height:0;border-top:2px solid #70807b}.rel-legend .issued{border-color:#62a9e8}.rel-legend .awarded{border-color:#b984df}.rel-legend .officer{border-color:#e58a58}.rel-legend .other{border-top-style:dashed}.canvas{position:relative;min-width:0;overflow:hidden;cursor:grab;touch-action:none;user-select:none;background:radial-gradient(circle at 50% 50%,#1c2a27 0,#111817 58%,#0b1110 100%);border-left:1px solid #293532;border-right:1px solid #293532}.canvas.dragging{cursor:grabbing}.canvas:before{content:'';position:absolute;inset:0;background-image:radial-gradient(#52635e 1px,transparent 1px);background-size:26px 26px;opacity:.18}.canvas svg{position:relative;width:100%;height:760px;display:block}.canvas line{stroke:#657873;stroke-width:2;opacity:.55}.canvas line.issued{stroke:#62a9e8;opacity:.62}.canvas line.awarded{stroke:#b984df;opacity:.62}.canvas line.officer{stroke:#e58a58;opacity:.62}.canvas .second-edge{stroke-width:1.6;opacity:.42}.canvas text{fill:#eef5f2;font-family:Arial,Helvetica,sans-serif;paint-order:stroke;stroke:#0d1412;stroke-width:5px;stroke-linejoin:round;pointer-events:none}.node{cursor:pointer}.node circle{stroke:#f0f6f4;stroke-width:2}.node.secondary circle{stroke-width:1.5}.node:hover circle,.node circle.selected{stroke-width:5;filter:drop-shadow(0 0 8px #ffffff55)}.node-label{font-size:16px;font-weight:600}.secondary-label{font-size:13px;fill:#d7e1dd}.center circle:first-child{stroke:#e4f8ef;stroke-width:3}.center .halo{fill:none;stroke:#55c88a;stroke-width:3;opacity:.28}.root-label{font-size:20px;font-weight:700}.root-type{font-size:12px;fill:#a9b8b3;text-transform:uppercase;letter-spacing:1px}.controls label{display:flex;flex-direction:column;gap:8px;margin:15px 0;color:#a8b5b1}.controls select{background:#192320;border:1px solid #40504c;color:#e5eeeb;padding:9px;font-size:12px}.controls .check{flex-direction:row;align-items:center}.controls p{line-height:1.5;color:#a7b4b0;margin:8px 0}.controls p b{color:#fff;font-size:15px}.controls .help{color:#7f8e89;margin-top:18px}.control-rule{border-top:1px solid #2b3734;margin:22px 0}.reset{margin-top:18px;width:100%}.inspector-top{display:flex;justify-content:space-between;align-items:center;margin-bottom:18px}.back{border:0;background:none;color:#9fb0aa;padding:0;cursor:pointer;font-size:11px}.type-dot{width:13px;height:13px;border-radius:50%;box-shadow:0 0 0 2px #ffffff20}.inspector>small{color:#82928d;text-transform:uppercase;letter-spacing:.08em;font-size:9px}.inspector h3{font-family:Georgia,'Times New Roman',serif;color:#fff;font-size:19px;line-height:1.2;margin:5px 0 10px}.relationship-pill{display:inline-block;border:1px solid #3b4a46;background:#17211e;color:#b8c7c2;padding:5px 7px;font-size:9px;text-transform:uppercase;letter-spacing:.07em;margin-bottom:20px}.inspector h4{color:#e9f1ee;font-size:12px;line-height:1.4;margin:0 0 8px}.inspector p{font-size:11px;line-height:1.55;color:#aebbb7}.meaning,.evidence{border-top:1px solid #2b3734;margin-top:18px;padding-top:16px}.meaning strong,.evidence strong{display:block;color:#fff;text-transform:uppercase;letter-spacing:.08em;font-size:9px;margin-bottom:7px}.evidence p{margin:2px 0}.inspector-links{display:flex;flex-direction:column;gap:9px;border-top:1px solid #2b3734;margin-top:18px;padding-top:16px}.inspector-links a{color:#83cdb1;font-size:11px;font-weight:700;text-decoration:none}.inspector-links a:hover{text-decoration:underline}.zoom{position:absolute;left:16px;bottom:16px;display:flex;align-items:center;background:#111a18;border:1px solid #35433f;color:#dce7e3;z-index:4}.zoom button{width:34px;height:32px;border:0;background:transparent;color:#fff;font-size:20px;cursor:pointer}.zoom span{min-width:52px;text-align:center;font-size:11px}.pan-hint{position:absolute;right:14px;bottom:18px;color:#7f8e89;font-size:10px;z-index:3;pointer-events:none}.graph-empty{position:absolute;inset:0;display:grid;place-items:center;color:#93a19c;font-size:14px}.graph-foot{display:flex;justify-content:space-between;gap:15px;background:#18211f;color:#9eada8;border:1px solid #293532;border-top:0;padding:10px 14px;font-size:11px}.graph-foot b{color:#dfe9e5}.graph-disclaimer{font-size:12px;line-height:1.5;color:#59635f;margin:12px 0 0}.graph-disclaimer strong{color:#202624;margin-right:4px}@media(max-width:950px){.graph-shell{grid-template-columns:160px minmax(0,1fr) 230px}.panel{padding:18px 12px}.canvas svg{height:680px}.graph-shell{min-height:680px}}@media(max-width:800px){.graph-shell{grid-template-columns:1fr;min-height:auto}.legend,.controls{display:none}.canvas{border:0}.canvas svg{height:600px}.head-actions span{display:none}.graph-foot{flex-direction:column}}@media(max-width:520px){.canvas svg{height:500px}.head-actions button{display:none}.graph-head h2{font-size:28px}}
</style>